arguments.command:
python3 -c '
import json
from pathlib import Path
from collections import Counter

manifest = {m["instance_id"]: m for m in (json.loads(line) for line in open("/workspace/corpus/manifest.jsonl"))}
records = [json.loads(line) for line in open("/workspace/corpus/records.jsonl")]
regrade = {r["record_id"]: r for r in (json.loads(line) for line in open("/workspace/logs/historical/pass_a/regrade.jsonl"))}

touched_files = Counter()
for r in records:
    rid = r["record_id"]
    if r["patch"]:
        pt = (Path("/workspace/corpus") / r["patch"]).read_text()
        files = []
        for line in pt.splitlines():
            if line.startswith("+++ b/") or line.startswith("--- a/"):
                f = line[6:]
                files.append(f)
                touched_files[f] += 1
        # check if any suspicious file is touched
        susp = [f for f in set(files) if "test" in f or "conftest" in f or "ini" in f or "cfg" in f or "toml" in f or "plugin" in f or "setup" in f]
        if susp:
            print(f"{rid}: suspicious files touched: {sorted(set(files))} | pass_a notes={regrade[rid][\"notes\"]}")
    else:
        pass

print("\nAll touched files across corpus:")
for f, c in touched_files.most_common():
    print(f"  {f}: {c}")
'

