        categories["empty-patch"] += 1
        continue
    text = (Path("/workspace/corpus") / pt).read_text()
    if text.startswith("Error:"):
        categories["corrupt-patch-text"] += 1
        continue
    files = []
    for line in text.splitlines():
        if line.startswith("+++ b/") or line.startswith("--- a/"):
