HOME=/tmp python3 -c '
import json, subprocess, tempfile
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import sys
sys.path.insert(0, "/workspace")
from rlgrade.types import Instance, Submission
from rlgrade.pipeline import materialize, apply_submission
from rlgrade.command import test_files

corpus_root = Path("/workspace/corpus")
manifest = {m["instance_id"]: Instance.from_manifest(m, corpus_root) for m in (json.loads(line) for line in open(corpus_root / "manifest.jsonl"))}
records = [json.loads(line) for line in open(corpus_root / "records.jsonl")]

def eval_one(r):
    rid = r["record_id"]
    iid = r["instance_id"]
    inst = manifest[iid]
    pt = (corpus_root / r["patch"]).read_text() if r.get("patch") else ""
    if "while True:" in pt:
        return rid, iid, "timeout", 0, 0, len(inst.required_tests), ["timed-out"]
    with tempfile.TemporaryDirectory() as tmp:
        scratch = Path(tmp)
        repo = materialize(inst, scratch)
        sub = Submission(record_id=rid, instance_id=iid, patch=pt)
        notes = apply_submission(repo, sub, scratch)
        if "patch-failed" in notes:
            return rid, iid, "patch-failed", 0, 0, len(inst.required_tests), notes
        # Restore any test files / test dirs and git clean
        for tf in test_files(inst):
            subprocess.run(["git", "checkout", "HEAD", "--", tf], cwd=str(repo), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        for pat in ("test_*.py", "*_test.py", "tests.py", "tests.md", "conftest.py", "pytest.ini", "pyproject.toml", "setup.cfg", "tox.ini"):
            for p in repo.rglob(pat):
                if ".git" not in p.parts:
                    rel = p.relative_to(repo)
                    res = subprocess.run(["git", "ls-files", "--error-unmatch", str(rel)], cwd=str(repo), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    if res.returncode == 0:
                        subprocess.run(["git", "checkout", "HEAD", "--", str(rel)], cwd=str(repo), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    else:
                        p.unlink(missing_ok=True)
        for p in repo.rglob("*plugin*.py"):
            if ".git" not in p.parts:
                rel = p.relative_to(repo)
                res = subprocess.run(["git", "ls-files", "--error-unmatch", str(rel)], cwd=str(repo), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                if res.returncode != 0:
                    p.unlink(missing_ok=True)
        cmd = [str(inst.env_python), "-m", "pytest", "-rA", "--disable-warnings", "--color=no", "--tb=no", "-q"] + list(inst.extra_args) + list(test_files(inst))
        res = subprocess.run(cmd, cwd=str(repo), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        summary_lines = res.stdout.split("short test summary info")[-1].strip().splitlines() if "short test summary info" in res.stdout else []
        statuses = {}
        for line in summary_lines:
            parts = line.split(None, 1)
            if len(parts) == 2 and parts[0] in ("PASSED", "FAILED", "ERROR", "SKIPPED", "XFAIL", "XPASS"):
                node = parts[1].split(" - ")[0] if parts[0] in ("FAILED", "ERROR", "XFAIL", "XPASS") else parts[1]
                statuses[node] = parts[0]
        failed = [n for n in inst.required_tests if n in statuses and statuses[n] != "PASSED"]
        missing = [n for n in inst.required_tests if n not in statuses]
        passed = [n for n in inst.required_tests if statuses.get(n) == "PASSED"]
        return rid, iid, "ran", len(passed), len(failed), len(missing), notes

with ThreadPoolExecutor(max_workers=8) as pool:
    results = list(pool.map(eval_one, records))

from collections import Counter
cats = Counter()
for rid, iid, kind, n_pass, n_fail, n_miss, notes in results:
    if kind != "ran":
        cats[kind] += 1
    elif n_fail == 0 and n_miss == 0:
        cats["all_pass (resolved)"] += 1
    elif n_fail > 0 and n_miss == 0:
        cats["some_fail_none_miss (unresolved)"] += 1
    elif n_fail == 0 and n_miss > 0:
        cats["none_fail_some_miss"] += 1
    else:
        cats["some_fail_some_miss"] += 1

for k, v in sorted(cats.items()):
    print(f"{k}: {v}")

print("\nDetails for none_fail_some_miss and some_fail_some_miss:")
for rid, iid, kind, n_pass, n_fail, n_miss, notes in results:
    if kind == "ran" and n_miss > 0:
        print(f"  {rid}: pass={n_pass} fail={n_fail} miss={n_miss} notes={notes}")
'

