from __future__ import annotations

import os
import shutil
import subprocess
from pathlib import Path
from typing import Sequence

TEST_FILE_PATTERNS = (
    "test_*.py",
    "*_test.py",
    "tests.py",
    "tests.md",
    "test_*.md",
    "*_test.md",
    "test_*.rst",
    "*_test.rst",
    "test_*.txt",
    "*_test.txt",
)

CONFIG_AND_HOOK_NAMES = (
    "conftest.py",
    "pytest.ini",
    ".pytest.ini",
    "pyproject.toml",
    "setup.cfg",
    "tox.ini",
    "sitecustomize.py",
    "usercustomize.py",
)

TEST_DIR_NAMES = ("test", "tests", "testing")


def _git(repo_root: Path, *args: str) -> subprocess.CompletedProcess:
    env = dict(os.environ)
    env["HOME"] = "/tmp"
    return subprocess.run(
        ["git", *args],
        cwd=str(repo_root),
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
    )


def _is_protected_path(rel_str: str) -> bool:
    rel = Path(rel_str)
    name = rel.name
    parts_lower = [p.lower() for p in rel.parts[:-1]]
    if any(p in TEST_DIR_NAMES for p in parts_lower):
        return True
    if name in CONFIG_AND_HOOK_NAMES or name.endswith(".pth"):
        return True
    if "plugin" in name.lower() and name.endswith(".py"):
        return True
    for pattern in TEST_FILE_PATTERNS:
        if rel.match(pattern):
            return True
    return False


def iter_test_files(repo_root: Path):
    """Every test or harness-config file of the checkout, as paths relative to the repository root."""
    seen: set[Path] = set()
    for pattern in TEST_FILE_PATTERNS + CONFIG_AND_HOOK_NAMES:
        for path in sorted(repo_root.rglob(pattern)):
            if ".git" in path.parts:
                continue
            rel = path.relative_to(repo_root)
            if rel not in seen:
                seen.add(rel)
                yield rel
    for path in sorted(repo_root.rglob("*")):
        if ".git" in path.parts or not path.is_file():
            continue
        rel = path.relative_to(repo_root)
        if rel not in seen and _is_protected_path(str(rel)):
            seen.add(rel)
            yield rel


def restore_tests(repo_root: Path, required_files: Sequence[str] = ()) -> list[str]:
    """Restore test files and pytest configuration to HEAD, removing untracked test/plugin files."""
    restored: list[str] = []
    seen: set[str] = set()

    def _record(rel_str: str) -> None:
        if rel_str not in seen:
            seen.add(rel_str)
            restored.append(rel_str)

    # 1. Restore any tracked files that were modified or deleted by the rollout.
    diff = _git(repo_root, "diff", "--name-only", "HEAD")
    tracked_targets: list[str] = []
    if diff.returncode == 0:
        for line in diff.stdout.splitlines():
            rel_str = line.strip()
            if rel_str and (_is_protected_path(rel_str) or rel_str in required_files):
                tracked_targets.append(rel_str)
                _record(rel_str)

    for req in required_files:
        if req and req not in seen:
            tracked_targets.append(req)
            _record(req)

    if tracked_targets:
        _git(repo_root, "checkout", "HEAD", "--", *tracked_targets)

    # 2. Remove any untracked test, config, hook, or plugin files created by the rollout.
    untracked = _git(repo_root, "ls-files", "--others", "--exclude-standard")
    if untracked.returncode == 0:
        for line in untracked.stdout.splitlines():
            rel_str = line.strip()
            if rel_str and (_is_protected_path(rel_str) or rel_str in required_files):
                target = repo_root / rel_str
                if target.is_dir():
                    shutil.rmtree(target, ignore_errors=True)
                elif target.exists() or target.is_symlink():
                    target.unlink(missing_ok=True)
                _record(rel_str)

    # 3. Also ensure any existing test files on disk match HEAD if tracked, or are removed if untracked.
    for rel in list(iter_test_files(repo_root)):
        rel_str = str(rel)
        if rel_str in seen:
            continue
        is_tracked = _git(repo_root, "ls-files", "--error-unmatch", rel_str).returncode == 0
        if is_tracked:
            _git(repo_root, "checkout", "HEAD", "--", rel_str)
        else:
            (repo_root / rel).unlink(missing_ok=True)
        _record(rel_str)

    return restored

