import json
from collections import defaultdict

with open("/workspace/logs/historical/pass_a/regrade.jsonl") as f:
    base = {r["record_id"]: r for r in map(json.loads, f)}
with open("/workspace/experiment_logs/regrade.jsonl") as f:
    reg = {r["record_id"]: r for r in map(json.loads, f)}

transitions = defaultdict(list)
unchanged = defaultdict(list)
for rid, b in base.items():
    r = reg[rid]
    b_key = (b["label"], b["reward"])
    r_key = (r["label"], r["reward"])
    if b_key != r_key:
        transitions[(b_key, r_key)].append(rid)
    else:
        unchanged[b_key].append(rid)

print("TRANSITIONS:")
for (bk, rk), rids in sorted(transitions.items()):
    print(f"  {bk} -> {rk}: {len(rids)} records")
    for rid in rids:
        print(f"    - {rid} (notes={reg[rid][\"notes\"]}, missing={reg[rid][\"missing\"]}, failed_cnt={len(reg[rid][\"failed\"])})")
print("UNCHANGED:")
for bk, rids in sorted(unchanged.items()):
    print(f"  {bk}: {len(rids)} records")
    for rid in rids:
        print(f"    - {rid}")
'

